#include "stdlib/stats/base/dists/gamma/deriv.h"
#include "stdlib/stats/base/dists/gamma/regularized_prefix.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/exp.h"
#include "stdlib/math/base/special/gammaln.h"
#include "stdlib/math/base/special/ln.h"
#include "stdlib/constants/float64/max.h"
#include "stdlib/constants/float64/pinf.h"

/**
* Calculates the partial derivative with respect to x of the incomplete gamma function.
*
* @private
* @param a  function parameter
* @param x  function parameter
* @return   function value
*/
double stdlib_base_dists_gamma_deriv( const double a, const double x ) {
	double f1;
	if ( a <= 0.0 ) {
		return 0.0/0.0; // NaN
	}
	if ( x < 0.0 ) {
		return 0.0/0.0; // NaN
	}
	if ( x == 0.0 ) {
		if ( a > 1.0 ) {
			return 0.0;
		}
		return ( a == 1.0 ) ? 1.0 : STDLIB_CONSTANT_FLOAT64_PINF;
	}
	f1 = stdlib_base_dists_gamma_regularized_prefix( a, x );
	if ( x < 1.0 && ( STDLIB_CONSTANT_FLOAT64_MAX * x < f1 ) ) {
		return STDLIB_CONSTANT_FLOAT64_PINF;
	}
	if ( f1 == 0.0 ) {
		// Underflow in calculation, use logs instead:
		f1 = (a * stdlib_base_ln( x )) - x - stdlib_base_gammaln( a ) - stdlib_base_ln( x );
		f1 = stdlib_base_exp( f1 );
	} else {
		f1 /= x;
	}
	return f1;
}
